def longest_common_prefix(strs: list[str]) -> str:
    if not strs:
        return ""

    # Sort the list to compare only the first and last strings
    # The common prefix of the whole list must be a prefix of the lexicographically first and last strings
    strs.sort()

    first = strs[0]
    last = strs[-1]
    result = []

    for i in range(min(len(first), len(last))):
        if first[i] == last[i]:
            result.append(first[i])
        else:
            break

    return "".join(result)
