def balanced_ternary_str(n: int) -> str:
    """
    Converts an integer n to its balanced ternary representation.
    Balanced ternary uses digits -1, 0, and 1.
    In the resulting string, '1' represents 1, '0' represents 0, and 'T' represents -1.
    """
    if n == 0:
        return "0"

    res = []
    is_negative = False

    # Handle negative numbers by converting to positive and flipping signs at the end
    temp_n = n
    if temp_n < 0:
        temp_n = -temp_n
        is_negative = True

    while temp_n > 0:
        remainder = temp_n % 3
        if remainder == 0:
            res.append("0")
            temp_n //= 3
        elif remainder == 1:
            res.append("1")
            temp_n //= 3
        else: # remainder == 2
            res.append("T")
            temp_n = (temp_n + 1) // 3

    # If the original number was negative, flip the signs of the balanced ternary digits
    if is_negative:
        flipped = []
        for char in res:
            if char == "1":
                flipped.append("T")
            elif char == "T":
                flipped.append("1")
            else:
                flipped.append("0")
        res = flipped

    return "".join(reversed(res))
