def prefix_suffix_common(s: str) -> int:
    """
    Returns the length of the longest proper prefix of s that is also a suffix of s.
    """
    n = len(s)
    if n < 2:
        return 0

    # Using the KMP preprocessing algorithm (Partial Match Table / LPS array)
    lps = [0] * n
    length = 0  # length of the previous longest proper prefix suffix
    i = 1

    while i < n:
        if s[i] == s[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1

    return lps[n - 1]

