def compact_matrix_dict(matrix: list[list[int]]) -> dict[tuple[int, int], int]:
    """
    Converts a 2D list matrix into a dictionary of non-zero elements.
    Keys are (row, col) tuples and values are the element values.
    """
    compact_dict = {}
    for r, row in enumerate(matrix):
        for c, val in enumerate(row):
            if val != 0:
                compact_dict[(r, c)] = val
    return compact_dict
