def weighted_edit_cost(source: str, target: str, insert_cost: int, delete_cost: int, replace_cost: int) -> int:
    m, n = len(source), len(target)

    # Create a DP table where dp[i][j] is the min cost to transform 
    # source[:i] to target[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base cases: transforming to/from an empty string
    for i in range(1, m + 1):
        dp[i][0] = i * delete_cost
    for j in range(1, n + 1):
        dp[0][j] = j * insert_cost

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if source[i - 1] == target[j - 1]:
                # Characters match, no cost added
                dp[i][j] = dp[i - 1][j - 1]
            else:
                # Consider all three operations and take the minimum
                dp[i][j] = min(
                    dp[i - 1][j] + delete_cost,    # Deletion
                    dp[i][j - 1] + insert_cost,    # Insertion
                    dp[i - 1][j - 1] + replace_cost # Replacement
                )

    return dp[m][n]
