def min_coins_bounded(coins: list[int], limits: list[int], target: int) -> int:
    if target == 0:
        return 0

    # dp[i] will store the minimum coins needed to reach amount i
    # Initialize with infinity
    dp = [float('inf')] * (target + 1)
    dp[0] = 0

    for coin_val, limit in zip(coins, limits):
        if limit == 0:
            continue

        # To optimize the bounded knapsack problem, we use a temporary array 
        # or process in a way that respects the limit.
        # We iterate backwards to avoid using the same coin instance multiple times
        # but since we have a limit, we can use a deque or a simple inner loop.
        for amount in range(target, 0, -1):
            for k in range(1, limit + 1):
                if amount - k * coin_val >= 0:
                    dp[amount] = min(dp[amount], dp[amount - k * coin_val] + k)
                else:
                    break

    return dp[target] if dp[target] != float('inf') else -1
