def longest_bitonic_length(nums: list[int]) -> int:
    if not nums:
        return 0

    n = len(nums)

    # LIS[i] will store the length of the longest strictly increasing 
    # subsequence ending at index i.
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # LDS[i] will store the length of the longest strictly decreasing 
    # subsequence starting at index i.
    lds = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if nums[i] > nums[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    # The longest bitonic subsequence length is the maximum of (LIS[i] + LDS[i] - 1)
    # because the element at index i is counted in both LIS and LDS.
    max_len = 0
    for i in range(n):
        max_len = max(max_len, lis[i] + lds[i] - 1)

    return max_len
