    Returns the length of the longest bitonic subsequence.
    A bitonic subsequence is a sequence that first increases and then decreases.
    """
    if not nums:
        return 0

    n = len(nums)

    # LIS[i] stores the length of the Longest Increasing Subsequence ending at index i
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # LDS[i] stores the length of the Longest Decreasing Subsequence starting at index i
    lds = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(n - 1, i, -1):
            if nums[i] > nums[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    max_len = 0
    for i in range(n):
        # The element at index i is counted in both lis and lds, so subtract 1
        max_len = max(max_len, lis[i] + lds[i] - 1)

    return max_len
