    # We use the path in the priority queue to handle the lexicographical requirement.
    # Since we want the lexicographically smallest path among those with the same min cost,
    # and heapq is a min-heap, this works naturally.
    pq = [(0, [start])]
    # visited stores the minimum cost to reach a node.
    # To handle lexicographical ties, we only update if cost is strictly less,
    # OR if cost is equal and the new path is lexicographically smaller.
    visited_costs = {start: 0}
    visited_paths = {start: [start]}

    while pq:
        current_cost, path = heapq.heappop(pq)
        u = path[-1]

