        # the first time we pop the goal, it's the cheapest.
        # However, we must be careful: multiple paths might have the same min cost.
        # The priority queue handles (cost, path) tuples, so it will pop the 
        # lexicographically smallest path among those with the same minimum cost.
        if u == goal:
            return (current_cost, path)

        # If we found a better path to u already, skip
        if current_cost > visited_costs.get(u, float('inf')):
            continue
        if current_cost == visited_costs.get(u) and path > visited_paths.get(u, []):
            continue

        for v, w in adj[u]:
            new_cost = current_cost + w
            new_path = path + [v]

