        return (0, [start])

    # Build adjacency list for undirected graph
    adj = defaultdict(list)
    for u, v, w in edges:
        adj[u].append((v, w))
        adj[v].append((u, w))

    # Priority Queue stores: (current_cost, path_as_list)
    # heapq will compare cost first, then the path list lexicographically
    pq = [(0, [start])]
    # visited stores the minimum cost to reach a node
    visited = {}

    while pq:
        cost, path = heapq.heappop(pq)
        current_node = path[-1]

        # If we reached the goal, since we use a priority queue, 
        # the first time we pop the goal, it's the cheapest and lexicographically smallest path.
        if current_node == goal:
            return (cost, path)

        # If we've reached this node before with a cheaper cost, skip
        if current_node in visited and visited[current_node] < cost:
            continue

        visited[current_node] = cost

        for neighbor, weight in adj[current_node]:
            new_cost = cost + weight
            new_path = path + [neighbor]

            # Only push to PQ if this path is potentially better or equal to known paths
            if neighbor not in visited or new_cost <= visited[neighbor]:
                heapq.heappush(pq, (new_cost, new_path))

    return None
