import heapq

def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    """
    Finds the cheapest route from start to goal using Dijkstra's algorithm.
    Returns a tuple of (total_cost, path_list) or None if no path exists.
    """
    # Build adjacency list
    graph = {}
    for u, v, weight in edges:
        if u not in graph:
            graph[u] = []
        graph[u].append((v, weight))

    # Priority queue stores (cumulative_cost, current_node, path_taken)
    pq = [(0, start, [start])]
    # Keep track of the minimum cost to reach each node to avoid redundant processing
    visited = {start: 0}

    while pq:
        current_cost, current_node, path = heapq.heappop(pq)

        if current_node == goal:
            return (current_cost, path)

        # If we found a cheaper way to this node already, skip
        if current_cost > visited.get(current_node, float('inf')):
            continue

        for neighbor, weight in graph.get(current_node, []):
            new_cost = current_cost + weight
            if new_cost < visited.get(neighbor, float('inf')):
                visited[neighbor] = new_cost
                heapq.heappush(pq, (new_cost, neighbor, path + [neighbor]))

    return None
