def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    if n <= 0:
        return []

    adj = [[] for _ in range(n)]
    in_degree = [0] * n

    for u, v in pairs:
        # Handle self-loops as cycles
        if u == v:
            return []
        # Ensure nodes are within valid range [0, n-1]
        if 0 <= u < n and 0 <= v < n:
            adj[u].append(v)
            in_degree[v] += 1
        else:
            # If input contains nodes outside range, it's technically invalid
            return []

    # Use a min-priority queue to ensure lexicographically smallest order
    pq = [i for i in range(n) if in_degree[i] == 0]
    heapq.heapify(pq)

    result = []
    while pq:
        u = heapq.heappop(pq)
        result.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(pq, v)

    # If result length is not n, a cycle exists
    if len(result) != n:
        return []

    return result

