import ast
import operator

def evaluate_expression(expr: str) -> int:
    """
    Evaluates a mathematical expression string containing integers and 
    basic operators (+, -, *, /) using a safe AST parser.
    """
    operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.floordiv,  # Using floor division to return int
        ast.USub: operator.neg,
    }

    def _eval(node):
        if isinstance(node, ast.Num):  # < Python 3.8
            return node.n
        elif isinstance(node, ast.Constant):  # >= Python 3.8
            return node.value
        elif isinstance(node, ast.BinOp):
            return operators[type(node.op)](_eval(node.left), _eval(node.right))
        elif isinstance(node, ast.UnaryOp):
            return operators[type(node.op)](_eval(node.operand))
        else:
            raise TypeError(f"Unsupported operation: {type(node)}")

    # Parse the expression into an AST and evaluate the body
    tree = ast.parse(expr, mode='eval')
    return int(_eval(tree.body))
