import re

def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    i = 0
    n = len(source)

    while i < n:
        char = source[i]

        # Skip whitespace
        if char.isspace():
            i += 1
            continue

        # Match NUMBER
        if char.isdigit():
            start = i
            while i < n and char.isdigit():
                i += 1
                if i < n: char = source[i]
            if i < n and char == '.':
                i += 1
                if i < n and source[i].isdigit():
                    while i < n and source[i].isdigit():
                        i += 1
                else:
                    # A dot not followed by a digit is invalid for a number
                    raise ValueError(f"Invalid character '.' at position {i-1}")
            tokens.append(("NUMBER", source[start:i]))
            continue

        # Match NAME
        if char.isalpha() or char == '_':
            start = i
            while i < n and (source[i].isalnum() or source[i] == '_'):
                i += 1
            tokens.append(("NAME", source[start:i]))
            continue

        # Match OP
        two_char_ops = {"==", "!=", "<=", ">="}
        if i + 1 < n and source[i:i+2] in two_char_ops:
            tokens.append(("OP", source[i:i+2]))
            i += 2
            continue

        single_char_ops = {'+', '-', '*', '/', '<', '>', '=', '(', ')', ','}
        if char in single_char_ops:
            tokens.append(("OP", char))
            i += 1
            continue

        # If no match is found
        raise ValueError(f"Unexpected character '{char}' at position {i}")

    return tokens
