def expand_template(template: str, values: dict[str, str]) -> str:
    result = []
    i = 0
    n = len(template)

    while i < n:
        # Check for {{
        if i + 1 < n and template[i] == '{' and template[i+1] == '{':
            result.append('{')
            i += 2
            continue

        # Check for }}
        if i + 1 < n and template[i] == '}' and template[i+1] == '}':
            result.append('}')
            i += 2
            continue

        # Check for start of placeholder {
        if template[i] == '{':
            # Look for the nearest following }
            end_index = template.find('}', i + 1)
            if end_index != -1:
                # Extract the key between { and }
                key = template[i + 1 : end_index]
                if key in values:
                    result.append(values[key])
                    i = end_index + 1
                else:
                    # Keep placeholder unchanged
                    result.append('{')
                    i += 1
            else:
                # No } found after this {, keep as ordinary character
                result.append('{')
                i += 1
        else:
            # Ordinary character or a single } not part of }}
            result.append(template[i])
            i += 1

    return "".join(result)
