def expand_template(template: str, values: dict[str, str]) -> str:
    result = []
    i = 0
    n = len(template)

    while i < n:
        # Handle double braces: {{ -> { and }} -> }
        if template.startswith('{{', i):
            result.append('{')
            i += 2
            continue
        if template.startswith('}}', i):
            result.append('}')
            i += 2
            continue

        # Check for potential placeholder start
        if template[i] == '{':
            # A placeholder starts if there is at least one '}' later in the string
