def decode_runs(encoded: str) -> str:
    result = []
    i = 0
    n = len(encoded)

    while i < n:
        # Determine the character of the token
        if encoded[i] == '\\':
            # Token is the character immediately following the backslash
            i += 1
            if i < n:
                char = encoded[i]
                i += 1
            else:
                # This case shouldn't happen based on "always correct structure"
                break
        else:
            # Token is a single character (not \, ~, or digit)
            char = encoded[i]
            i += 1

        # Check if the token is followed by a run indicator '~n'
        if i < n and encoded[i] == '~':
            i += 1
            num_start = i
            while i < n and encoded[i].isdigit():
                i += 1

            # Extract the number n
            num_str = encoded[num_start:i]
            count = int(num_str) if num_str else 0
            result.append(char * count)
        else:
            # No run indicator, character appears once
            result.append(char)

    return "".join(result)

