def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end:
        return []

    # Filter out empty ranges and clip ranges to the day boundaries
    clipped = []
    for s, e in busy:
        if s < e:
            # Only consider the part of the busy range that falls within the day
            start = max(s, day_start)
            end = min(e, day_end)
            if start < end:
                clipped.append((start, end))

    # Merge overlapping or touching busy ranges
    if not clipped:
        merged = []
    else:
        clipped.sort()
        merged = []
        curr_start, curr_end = clipped[0]
        for next_start, next_end in clipped[1:]:
            if next_start <= curr_end:
                curr_end = max(curr_end, next_end)
            else:
                merged.append((curr_start, curr_end))
                curr_start, curr_end = next_start, next_end
        merged.append((curr_start, curr_end))

    # Find gaps between merged busy ranges within the day boundaries
    free = []
    last_end = day_start
    for start, end in merged:
        if start - last_end >= min_len:
            free.append((last_end, start))
        last_end = end

    # Check the final gap after the last busy range
    if day_end - last_end >= min_len:
        free.append((last_end, day_end))

    return free
