from collections import deque

def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    # queues maps item name to a deque of quantities waiting to be shipped
    queues = {}
    # global_waiting tracks the order of orders placed across all items
    # We store them as [item, quantity, processed_flag] to handle removal/tracking
    global_waiting = []

    for kind, item, quantity in events:
        if item not in stock:
            stock[item] = 0
        if item not in queues:
            queues[item] = deque()

        if kind == 'receive':
            stock[item] += quantity
            # Process the queue for this specific item
            while queues[item] and stock[item] >= queues[item][0]:
                ship_qty = queues[item].popleft()
                stock[item] -= ship_qty
                # Mark this specific order as processed in the global list
                # We find the first occurrence of this item/qty that is not yet processed
                for entry in global_waiting:
                    if entry[0] == item and entry[1] == ship_qty and not entry[2]:
                        entry[2] = True
                        break

        elif kind == 'order':
            # An order is shipped immediately if:
            # 1. No earlier order for the same item is waiting
            # 2. Stock is sufficient
            if not queues[item] and stock[item] >= quantity:
                stock[item] -= quantity
            else:
                # Join the waiting queue
                queues[item].append(quantity)
                global_waiting.append([item, quantity, False])

    # Filter global_waiting to only include those not processed
    final_waiting = [(item, qty) for item, qty, processed in global_waiting if not processed]

    return stock, final_waiting
