def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting_queues = {}

    for kind, item, quantity in events:
        if item not in stock:
            stock[item] = 0
            waiting_queues[item] = deque()

        if kind == 'receive':
            stock[item] += quantity
            # Process waiting queue for this item
            while waiting_queues[item]:
                next_qty = waiting_queues[item][0]
                if stock[item] >= next_qty:
                    stock[item] -= next_qty
                    waiting_queues[item].popleft()
                else:
                    break
        elif kind == 'order':
            # Order ships immediately if no one is waiting and stock is sufficient
            if not waiting_queues[item] and stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting_queues[item].append(quantity)

    # Collect all remaining waiting orders in the order they were placed
    # To maintain global order, we need to track the sequence of orders.
    # Let's refine the logic to track global order of waiting items.

    # Re-simulating with a global sequence tracker for waiting orders
    stock = {}
    waiting_queues = {} # item -> deque of (order_id, quantity)
    global_order_counter = 0

    for kind, item, quantity in events:
        if item not in stock:
            stock[item] = 0
            waiting_queues[item] = deque()

        if kind == 'receive':
            stock[item] += quantity
            while waiting_queues[item]:
                order_id, next_qty = waiting_queues[item][0]
                if stock[item] >= next_qty:
                    stock[item] -= next_qty
                    waiting_queues[item].popleft()
                else:
                    break
        elif kind == 'order':
            if not waiting_queues[item] and stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting_queues[item].append((global_order_counter, quantity))
                global_order_counter += 1

    # Flatten all waiting queues and sort by order_id
    all_waiting = []
    for item, queue in waiting_queues.items():
        for order_id, qty in queue:
            all_waiting.append((order_id, item, qty))

    all_waiting.sort() # Sort by order_id
    final_waiting = [(item, qty) for order_id, item, qty in all_waiting]

    return stock, final_waiting

