def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    # queues stores a deque of quantities for each item: {item: deque([qty1, qty2, ...])}
    queues = {}
    # To keep track of the global order of waiting orders for the final output
    # We store (item, quantity) in a list and remove them when processed
    global_waiting_list = []

    for kind, item, quantity in events:
        if item not in stock:
            stock[item] = 0
        if item not in queues:
            queues[item] = deque()

        if kind == 'receive':
            stock[item] += quantity
            # Process the queue for this specific item
            while queues[item] and stock[item] >= queues[item][0]:
                qty_to_remove = queues[item].popleft()
                stock[item] -= qty_to_remove
                # Remove the first occurrence of this specific order from the global list
                for i in range(len(global_waiting_list)):
                    if global_waiting_list[i] == (item, qty_to_remove):
                        global_waiting_list.pop(i)
                        break

        elif kind == 'order':
            # An order is processed immediately ONLY IF:
            # 1. No previous orders for this item are waiting
            # 2. There is enough stock
            if not queues[item] and stock[item] >= quantity:
                stock[item] -= quantity
            else:
                # Otherwise, it goes to the queue
                queues[item].append(quantity)
                global_waiting_list.append((item, quantity))

    return stock, global_waiting_list
