from collections import deque

def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    # queues stores a deque of quantities for each item: {item: deque([qty1, qty2, ...])}
    queues = {}
    # To maintain the global order of waiting orders for the final output
    # We store (item, quantity) in a list and remove them when processed.
    # However, a simpler way is to track which orders are still pending.
    # Let's use a list of lists to track the global sequence of orders.
    global_waiting_list = [] 
    # To efficiently remove from global_waiting_list, we can store references or 
    # just rebuild the list at the end based on the per-item queues.
    # But the prompt asks for orders in the order they were made.

    # We will track the order of items in a global list and use a flag to mark them as 'processed'
    # Or more simply: keep a list of all orders and a pointer/index for each item's queue.

    # Let's use a dictionary of deques for the logic and a list to track the original order of orders.
    order_history = [] # List of [item, quantity, is_processed]

    for kind, item, quantity in events:
        if item not in stock:
            stock[item] = 0
        if item not in queues:
            queues[item] = deque()

        if kind == 'receive':
            stock[item] += quantity
            # Process the queue for this specific item
            while queues[item]:
                next_qty = queues[item][0]
                if stock[item] >= next_qty:
                    stock[item] -= next_qty
                    queues[item].popleft()
                    # Mark this specific order as processed in the global history
                    # We find the first unprocessed order for this item
                    for entry in order_history:
                        if entry[0] == item and not entry[2]:
                            entry[2] = True
                            break
                else:
                    break

        elif kind == 'order':
            # An order is processed immediately ONLY IF:
            # 1. No previous orders for this item are waiting
            # 2. Inventory is sufficient
            if not queues[item] and stock[item] >= quantity:
                stock[item] -= quantity
            else:
                # Add to item queue and global history
                queues[item].append(quantity)
                order_history.append([item, quantity, False])

    # Construct the final waiting list based on the global history of unprocessed orders
    waiting = [(item, qty) for item, qty, processed in order_history if not processed]

    return stock, waiting
