def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    ip = 0
    instructions_executed = 0
    max_instructions = 1000

    while ip < len(program):
        if instructions_executed >= max_instructions:
            return None

        instr = program[ip]
        parts = instr.split()
        op = parts[0]

        instructions_executed += 1

        if op == "PUSH":
            stack.append(int(parts[1]))
            ip += 1
        elif op == "POP":
            if not stack: return None
            stack.pop()
            ip += 1
        elif op == "DUP":
            if not stack: return None
            stack.append(stack[-1])
            ip += 1
        elif op == "SWAP":
            if len(stack) < 2: return None
            stack[-1], stack[-2] = stack[-2], stack[-1]
            ip += 1
        elif op in ("ADD", "SUB", "MUL"):
            if len(stack) < 2: return None
            b = stack.pop()
            a = stack.pop()
            if op == "ADD":
                stack.append(a + b)
            elif op == "SUB":
                stack.append(a - b)
            elif op == "MUL":
                stack.append(a * b)
            ip += 1
        elif op == "JMP":
            ip = int(parts[1])
        elif op == "JZ":
            if not stack: return None
            val = stack.pop()
            if val == 0:
                ip = int(parts[1])
            else:
                ip += 1
        else:
            ip += 1

    return stack
