    digits = "0123456789abcdefghijklmnopqrstuvwxyz"

    # Handle sign
    is_negative = False
    start_idx = 0
    if number[0] == '-':
        is_negative = True
        start_idx = 1
        if len(number) == 1:
            raise ValueError("Invalid input number")

    # Convert from_base to decimal (int)
    try:
        decimal_value = int(number[start_idx:], from_base)
    except ValueError:
        raise ValueError("Invalid character for the given from_base")

    # Check if any characters in the number string were invalid for from_base
    # (int() handles this, but we must ensure no characters outside the base range were used)
    for char in number[start_idx:].lower():
        if char not in digits[:from_base]:
            raise ValueError("Invalid character for the given from_base")

    if decimal_value == 0:
        return "0"

    # Convert decimal to to_base
    res = []
    temp_val = abs(decimal_value)
    while temp_val > 0:
        res.append(digits[temp_val % to_base])
        temp_val //= to_base

    result_str = "".join(reversed(res))
    return f"-{result_str}" if is_negative else result_str

