from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    if not grid or not grid[0]:
        return -1

    rows = len(grid)
    cols = len(grid[0])
    start_pos = None
    end_pos = None

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start_pos = (r, c)
            elif grid[r][c] == 'E':
                end_pos = (r, c)

    # State: (row, col, has_broken_wall)
    # visited[row][col][0] -> visited without breaking a wall
    # visited[row][col][1] -> visited after breaking a wall
    visited = [[[False] * 2 for _ in range(cols)] for _ in range(rows)]

    queue = deque([(start_pos[0], start_pos[1], 0, 0)]) # r, c, broken, dist
    visited[start_pos[0]][start_pos[1]][0] = True

    while queue:
        r, c, broken, dist = queue.popleft()

        if (r, c) == end_pos:
            return dist

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nr, nc = r + dr, c + dc

            if 0 <= nr < rows and 0 <= nc < cols:
                is_wall = grid[nr][nc] == '#'

                if not is_wall:
