                    current_grid[r][c] -= 4
                    # Distribute to neighbors
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            current_grid[nr][nc] += 1

                    unstable_found = True
                    # Since a topple can make neighbors unstable, 
                    # we restart the check or continue until no more are found.
                    # To ensure correctness and simplicity, we break and check again.
                    break
            if unstable_found:
                break

        if not unstable_found:
            break

    return current_grid

