        # Use the RestrictedUnpickler to deserialize the data
        file_like_object = io.BytesIO(data)
        session = RestrictedUnpickler(file_like_object).load()

        if not isinstance(session, dict):
            raise ValueError("Restored session is not a dictionary")

        # Validate the contents of the dictionary to ensure it matches the expected schema
        for key, value in session.items():
