import pickle
import hmac
import hashlib

# একটি গোপন কী (Secret Key) যা সেশনের সত্যতা যাচাই করতে ব্যবহৃত হবে।
# বাস্তব অ্যাপ্লিকেশনে এটি এনভায়রনমেন্ট ভেরিয়েবল থেকে আসা উচিত।
SECRET_KEY = b'your-secure-secret-key-here'

def restore_session(data: bytes) -> dict:
    """
    বাইট ডাটা থেকে সেশন পুনরুদ্ধার করে। 
    pickle-এর নিরাপত্তা ঝুঁকি এড়াতে HMAC সিগনেচার যাচাই করা হয়।
    """
    try:
        # ডাটা ফরম্যাট: [signature (32 bytes)] + [pickled_data]
        signature = data[:32]
        payload = data[32:]

        # HMAC ব্যবহার করে ডাটার সত্যতা যাচাই (Integrity Check)
        expected_signature = hmac.new(SECRET_KEY, payload, hashlib.sha256).digest()

        if not hmac.compare_digest(signature, expected_signature):
            raise ValueError("Invalid session signature: Data may have been tampered with.")

        # শুধুমাত্র যাচাইকৃত ডাটাই আনপিকল করা হবে
        session = pickle.loads(payload)

        if not isinstance(session, dict):
            raise TypeError("Restored session must be a dictionary.")

        # ডাটা টাইপ ভ্যালিডেশন (কী: স্ট্রিং, মান: int, str, বা list[int, str])
        for key, value in session.items():
            if not isinstance(key, str):
                raise TypeError(f"Session key {key} must be a string.")

            if not isinstance(value, (int, str, list)):
                raise TypeError(f"Invalid value type for key {key}.")

            if isinstance(value, list):
                for item in value:
                    if not isinstance(item, (int, str)):
                        raise TypeError(f"List items for key {key} must be integers or strings.")

        return session

    except (pickle.UnpicklingError, AttributeError, EOFError, ValueError, TypeError) as e:
        # নিরাপত্তা নিশ্চিত করতে নির্দিষ্ট এরর মেসেজ বা খালি ডিকশনারি রিটার্ন করা
        print(f"Session restoration failed: {e}")
        return {}
