        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
    }

    def evaluate(node):
        if isinstance(node, ast.Expression):
            return evaluate(node.body)

        elif isinstance(node, ast.Constant):  # Python 3.8+ handles strings, ints, floats, bools
            return node.value

        elif isinstance(node, ast.Name):
            if node.id in record:
                return record[node.id]
            raise ValueError(f"Variable '{node.id}' not found in record")

        elif isinstance(node, ast.UnaryOp):
            op_type = type(node.op)
            if op_type not in operators:
                raise ValueError(f"Unsupported unary operator: {op_type}")
            return operators[op_type](evaluate(node.operand))

