                right = _eval(node.right)
                if isinstance(node.op, ast.Add): return left + right
                if isinstance(node.op, ast.Sub): return left - right
                if isinstance(node.op, ast.Mult): return left * right
                if isinstance(node.op, ast.Div): return left / right
                if isinstance(node.op, ast.Pow): return left ** right
                raise ValueError(f"Unsupported operator: {type(node.op)}")
            elif isinstance(node, ast.UnaryOp):
                operand = _eval(node.operand)
                if isinstance(node.op, ast.USub): return -operand
                if isinstance(node.op, ast.UAdd): return operand
                raise ValueError(f"Unsupported unary operator: {type(node.op)}")
            elif isinstance(node, ast.Name):
                if node.id in allowed_names:
                    return allowed_names[node.id]
                raise ValueError(f"Unsupported variable or function: {node.id}")
            elif isinstance(node, ast.Call):
                func = _eval(node.func)
                if not callable(func):
                    raise ValueError("Call target is not a function")
                if len(node.args) != 1:
                    raise ValueError("Functions must have exactly one argument")
                arg = _eval(node.args[0])
                return func(arg)
            else:
                raise ValueError(f"Unsupported syntax element: {type(node)}")

        return float(_eval(tree.body))

    except ZeroDivisionError:
        raise ZeroDivisionError("Division by zero")
    except (SyntaxError, TypeError, ValueError) as e:
        raise ValueError(f"Invalid formula: {e}")
    except Exception as e:
        # Catch other potential math errors (like sqrt of negative) as ValueErrors
