    allowed_names = {
        'x': x,
        'sqrt': math.sqrt,
        'abs': abs,
        'sin': math.sin,
        'cos': math.cos
    }

    # Allowed AST nodes for security
    allowed_nodes = {
        ast.Expression,
        ast.BinOp,
        ast.UnaryOp,
        ast.Num,
        ast.Constant, # For Python 3.8+
        ast.Name,
        ast.Load,
        ast.Call,
    }

    # Allowed operators
    allowed_ops = {
        ast.Add, ast.Sub, ast.Mult, ast.Div, ast.Pow, ast.USub, ast.UAdd
    }

    try:
        # Parse the formula into an AST
        tree = ast.parse(formula, mode='eval')

        # Validate the AST to prevent arbitrary code execution
        for node in ast.walk(tree):
            if type(node) not in allowed_nodes:
                raise ValueError(f"Unsupported operation: {type(node).__name__}")

            if isinstance(node, ast.Name):
                if node.id not in allowed_names:
                    raise ValueError(f"Unsupported variable or function: {node.id}")

            if isinstance(node, ast.BinOp):
                if type(node.op) not in allowed_ops:
                    raise ValueError(f"Unsupported operator: {type(node.op).__name__}")

            if isinstance(node, ast.UnaryOp):
                if type(node.op) not in allowed_ops:
                    raise ValueError(f"Unsupported unary operator: {type(node.op).__name__}")

        # Evaluate the expression using a restricted environment
        # We use a custom visitor or eval with restricted globals/locals
        # Since we already validated the AST, eval is safe here.
        result = eval(compile(tree, '<string>', 'eval'), {"__builtins__": None}, allowed_names)

        return float(result)

    except ZeroDivisionError:
        raise ZeroDivisionError("Division by zero")
    except (SyntaxError, TypeError) as e:
        raise ValueError(f"Invalid formula syntax: {e}")
    except Exception as e:
        # Catch other potential math errors (like sqrt of negative) as ValueError
        raise ValueError(f"Error evaluating formula: {e}")
