def is_valid_email(s: str) -> bool:
    # Ensure there is exactly one '@'
    if s.count('@') != 1:
        return False

    local, domain = s.split('@')

    # Local part validation
    # 1. Must not be empty
    if not local:
        return False
    # 2. Starts and ends with letter or digit
    if not (local[0].isalnum() and local[-1].isalnum()):
        return False
    # 3. Allowed characters: letters, digits, '.', '_', '-'
    # 4. No two separator characters next to each other
    for i in range(len(local)):
        char = local[i]
        if not (char.isalnum() or char in '._-'):
            return False
        if i > 0:
            prev = local[i-1]
            if (not char.isalnum()) and (not prev.isalnum()):
                return False

    # Domain part validation
    # 1. Must contain at least two labels separated by single dots
    if not domain or '.' not in domain:
        return False

    labels = domain.split('.')
    if len(labels) < 2:
        return False

    # 2. Each label is a non-empty sequence of ASCII letters and digits
    for label in labels:
        if not label or not label.isalnum():
            return False

    # 3. The last label consists of at least two ASCII letters and nothing else
    last_label = labels[-1]
    if len(last_label) < 2 or not last_label.isalpha():
        return False

    return True
