import re

def is_valid_email(s: str) -> bool:
    if s.count('@') != 1:
        return False

    local, domain = s.split('@')

    # Local part validation
    # 1. Must start and end with letter or digit
    if not local or not (local[0].isalnum() and local[-1].isalnum()):
        return False

    # 2. Allowed characters: alphanumeric, '.', '_', '-'
    # 3. No two separator characters next to each other
    for i in range(len(local)):
        char = local[i]
        if not (char.isalnum() or char in '._-'):
            return False
        if i > 0:
            prev = local[i-1]
            if (not char.isalnum()) and (not prev.isalnum()):
                return False

    # Domain part validation
    # 1. At least two labels separated by single dots
    labels = domain.split('.')
    if len(labels) < 2:
        return False

    # 2. Each label is a non-empty sequence of ASCII letters and digits
    for label in labels:
        if not label or not label.isalnum():
            return False

    # 3. The last label consists of at least two ASCII letters and nothing else
    last_label = labels[-1]
    if len(last_label) < 2 or not last_label.isalpha():
        return False

    return True
