def is_valid_email(s: str) -> bool:
    """
    Validates an email address based on specific constraints:
    - Exactly one '@' separating local and domain parts.
    - Local part: ASCII letters, digits, '.', '_', '-'. 
      Must start and end with alphanumeric, no consecutive separators.
    - Domain part: At least two labels separated by a single '.'.
      Labels must be alphanumeric. The last label must be at least 2 ASCII letters.
    """
    if s.count('@') != 1:
        return False

    local, domain = s.split('@')

    # Local part validation
    # Must start and end with alphanumeric
    if not local or not (local[0].isalnum() and local[-1].isalnum()):
        return False

    # Check for allowed characters and consecutive separators
    # Separators: . _ -
    separators = {'.', '_', '-'}
    for i in range(len(local)):
        char = local[i]
        if not (char.isalnum() or char in separators):
            return False
        if i > 0 and char in separators and local[i-1] in separators:
            return False

    # Domain part validation
    # Must contain at least one dot to have at least two labels
    if '.' not in domain:
        return False

    labels = domain.split('.')
    if len(labels) < 2:
        return False

    for i in range(len(labels)):
