def get_users_by_ids(conn, ids: list) -> list[tuple]:
    if not ids:
        return []

    # Convert all ids to integers to ensure consistency and basic validation
    try:
        # Using a set to remove duplicates and ensure unique IDs
        unique_ids = {int(user_id) for user_id in ids}
    except (ValueError, TypeError):
        # In a real scenario, you might want to handle non-numeric strings differently
