    # We generate a comma-separated string of placeholders like (?, ?, ?)
    placeholders = ', '.join(['?'] * len(unique_ids))
    query = f"SELECT id, username FROM users WHERE id IN ({placeholders}) ORDER BY id ASC"

    cursor = conn.cursor()
    # Pass the unique_ids as a tuple to the execute method for safe parameter binding
    cursor.execute(query, tuple(unique_ids))

    return cursor.fetchall()
